cat > internal/cli/debug5_test.go << 'EOF'
package cli

import (
	"bytes"
	"fmt"
	"testing"

	"github.com/spf13/cobra"
)

func TestDebugHelp5(t *testing.T) {
	var out bytes.Buffer

	cmd := &cobra.Command{
		Use:   "fractals",
		Short: "Generate ASCII art fractals",
		Long:  "Generate ASCII art fractals from the command line.",
	}

	cmd.SetOut(&out)
	// Try calling Help explicitly
	cmd.Help()

	fmt.Printf("Help output:\n%s\n", out.String())
}
EOF
go test ./internal/cli -run TestDebugHelp5 -count=1 -v 2>&1 | grep -A 15 "TestDebugHelp5"

